# Exercise the fitting interface on a short portion of the package's simulated
# trajectory and controls generated by the package itself.
library(hmmSSF)
data("track", package = "hmmSSF")
set.seed(4258)
dat <- get_controls(obs = track[seq_len(60), ], n_controls = 5, distr = "gamma")
ssf_par0 <- matrix(c(-5, -0.5, -1, -1, 0.2, 5), ncol = 2, byrow = TRUE)
fit <- suppressWarnings(hmmSSF(
  ssf_formula = ~step + log(step) + cos(angle),
  n_states = 2, data = dat, ssf_par0 = ssf_par0,
  method = "BFGS", optim_opts = list(maxit = 10),
  multistart = TRUE, diagnose = TRUE,
  multistart_opts = list(n_starts = 2, n_long = 1, short_maxit = 5,
                         jitter_sd = 0.05, seed = 42)
))
stopifnot(inherits(fit, "hmmSSF"), is.finite(fit$fit$value),
          nrow(fit$multistart$summary) == 3L,
          is.numeric(fit$diagnostics$max_abs_gradient),
          all(fit$multistart$summary$rejected_evaluations >= 0L))

# Compare the returned objective with an independent log-scale calculation of
# the finite-control likelihood and forward recursion for this two-state fit.
mm <- model.matrix(~step + log(step) + cos(angle), dat)[, -1, drop = FALSE]
lp <- mm %*% fit$par$ssf
logsumexp <- function(x) {
  m <- max(x)
  if (is.infinite(m) && m < 0) return(-Inf)
  m + log(sum(exp(x - m)))
}
strata <- split(seq_len(nrow(dat)), dat$stratum, drop = TRUE)
log_density <- t(vapply(strata, function(idx) {
  stopifnot(dat$obs[idx[1]] == 1L, sum(dat$obs[idx]) == 1L)
  vapply(seq_len(2L), function(s) {
    lp[idx[1], s] - logsumexp(lp[idx, s] - log(dat$w[idx])) + log(length(idx) - 1L)
  }, numeric(1))
}, numeric(2)))
p12 <- plogis(fit$par$tpm[1, 1])
p21 <- plogis(fit$par$tpm[1, 2])
transition <- matrix(c(1 - p12, p12, p21, 1 - p21), nrow = 2, byrow = TRUE)
initial <- c(p21, p12) / (p12 + p21)
log_alpha <- log(initial) + log_density[1, ]
for (i in 2:nrow(log_density)) {
  log_alpha <- log_density[i, ] + vapply(seq_len(2L), function(s) {
    logsumexp(log_alpha + log(transition[, s]))
  }, numeric(1))
}
independent_objective <- -logsumexp(log_alpha)
stopifnot(abs(independent_objective - fit$fit$value) < 1e-7)
